export interface WorkflowStageAlert {
  flow: string;
  role: string;
  department: string;
  stageKey: string;
  stageTitle: string;
  pendingCount: number;
  voiceText: string;
}

export const ALERT_ROLES = [
  { key: 'ALL', label: 'Barcha xizmatlar (Umumiy navbatchilik)' },
  { key: 'Security', label: 'Qo‘riqlash xizmati' },
  { key: 'Permit', label: 'Ruxsatnoma byurosi' },
  { key: 'Dispatching', label: 'ICHDX smena boshlig‘i' },
  { key: 'Scale', label: 'Tarozi operatori' },
  { key: 'Railway', label: 'Temir yo‘l sexi' },
  { key: 'Warehouse', label: 'TM va XA sexi' },
  { key: 'Economist', label: 'ICHDX iqtisodchisi' },
];

// O'rnatilgan Ding-Dong chime ovozi (Base64 WAV)
const CHIME_B64 = "";

let audioCtx: AudioContext | null = null;
let lastAnnouncedTimes: Record<string, number> = {};
let pendingQueuedAlert: string | null = null;
const ANNOUNCE_COOLDOWN_MS = 3 * 60 * 1000; // 3 daqiqa qayta takrorlanish oralig'i

function getAudioContext(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (AudioContextClass) {
      audioCtx = new AudioContextClass();
    }
  }
  return audioCtx;
}

// Foydalanuvchi sahifaga ilk bor harakat/bosish qilgan zahoti Audio tizimini blokdan chiqarish
if (typeof window !== 'undefined') {
  const unlockAudioPipeline = async () => {
    try {
      const ctx = getAudioContext();
      if (ctx && ctx.state === 'suspended') {
        await ctx.resume();
      }
      if (pendingQueuedAlert) {
        const text = pendingQueuedAlert;
        pendingQueuedAlert = null;
        void announceAlert(text);
      }
    } catch {}
  };

  ['click', 'pointerdown', 'keydown', 'touchstart'].forEach(evt => {
    window.addEventListener(evt, unlockAudioPipeline, { passive: true });
    document.addEventListener(evt, unlockAudioPipeline, { passive: true });
  });
}

/** Jarangdor va aniq eshitiluvchi signal (Ding-Dong Chime) */
export async function playChime(volume = 1.0): Promise<void> {
  // 1-usul: Web Audio API orqali sintez
  try {
    const ctx = getAudioContext();
    if (ctx) {
      if (ctx.state === 'suspended') {
        await ctx.resume().catch(() => {});
      }
      if (ctx.state === 'running') {
        const now = ctx.currentTime;
        const gainNode = ctx.createGain();
        gainNode.connect(ctx.destination);
        gainNode.gain.setValueAtTime(0.001, now);
        gainNode.gain.linearRampToValueAtTime(Math.min(1.0, Math.max(0.1, volume * 0.6)), now + 0.04);
        gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.7);

        // 1-ton (E5 - 659.25 Hz)
        const osc1 = ctx.createOscillator();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(659.25, now);
        osc1.connect(gainNode);
        osc1.start(now);
        osc1.stop(now + 0.3);

        // 2-ton (A5 - 880 Hz)
        const osc2 = ctx.createOscillator();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(880.0, now + 0.16);
        osc2.connect(gainNode);
        osc2.start(now + 0.16);
        osc2.stop(now + 0.7);

        await new Promise(r => setTimeout(r, 650));
        return;
      }
    }
  } catch {}

  // 2-usul: HTML5 Audio Base64 Chime (agar Web Audio API bloklangan bo'lsa)
  try {
    const audio = new Audio('data:audio/wav;base64,' + CHIME_B64);
    audio.volume = Math.min(1.0, Math.max(0.1, volume));
    await audio.play();
    await new Promise(r => setTimeout(r, 650));
  } catch {}
}

/** Asinxron SpeechSynthesis ovozlarini yuklab olish */
function getVoicesAsync(): Promise<SpeechSynthesisVoice[]> {
  return new Promise((resolve) => {
    if (typeof window === 'undefined' || !('speechSynthesis' in window)) {
      resolve([]);
      return;
    }
    const immediate = window.speechSynthesis.getVoices();
    if (immediate && immediate.length > 0) {
      resolve(immediate);
      return;
    }
    const timer = setTimeout(() => {
      resolve(window.speechSynthesis.getVoices() || []);
    }, 800);
    window.speechSynthesis.onvoiceschanged = () => {
      clearTimeout(timer);
      resolve(window.speechSynthesis.getVoices() || []);
    };
  });
}

/** Ovozli nutqni (Text-To-Speech) o'qish - ko'p tilli moslashuvchan mexanizm */
export async function speakText(text: string, volume = 1.0): Promise<void> {
  if (typeof window === 'undefined' || !('speechSynthesis' in window)) return;

  try {
    window.speechSynthesis.cancel();

    // Fonetikani yaxshilash va qulay talaffuz
    const cleanText = text
      .replace(/ICHDX/g, 'I-Che-De-Iks')
      .replace(/TM va XA/g, 'Te-Em va Xa-A')
      .replace(/E-Transport/g, 'E Transport');

    const utterance = new SpeechSynthesisUtterance(cleanText);
    utterance.rate = 0.95;
    utterance.pitch = 1.0;
    utterance.volume = Math.min(1.0, Math.max(0.1, volume));

    const voices = await getVoicesAsync();
    
    // Ovoz tanlash ustuvorligi:
    // 1. O'zbek tili (uz-UZ)
    // 2. Turk tili (tr-TR - lotin alifbosidagi o'zbekcha so'zlarni ravon va xatosiz o'qiydi)
    // 3. Rus tili (ru-RU)
    // 4. Standart tizim ovozi
    const uzVoice = voices.find(v => v.lang.toLowerCase().startsWith('uz'));
    const trVoice = voices.find(v => v.lang.toLowerCase().startsWith('tr'));
    const ruVoice = voices.find(v => v.lang.toLowerCase().startsWith('ru'));
    const defVoice = voices.find(v => v.default) || (voices.length > 0 ? voices[0] : null);

    const chosenVoice = uzVoice || trVoice || ruVoice || defVoice;
    if (chosenVoice) {
      utterance.voice = chosenVoice;
      utterance.lang = chosenVoice.lang;
    } else {
      utterance.lang = 'uz-UZ';
    }

    return new Promise((resolve) => {
      let hasFinished = false;
      const finish = () => {
        if (!hasFinished) {
          hasFinished = true;
          resolve();
        }
      };

      utterance.onend = finish;
      utterance.onerror = (e) => {
        // Agar autoplay bloklangan bo'lsa, navbatga qo'yib turadi
        if ((e as unknown as { error?: string }).error === 'not-allowed') {
          pendingQueuedAlert = text;
        }
        finish();
      };

      window.speechSynthesis.speak(utterance);
      // Qotib qolmasligi uchun xavfsizlik taymeri
      setTimeout(finish, 8500);
    });
  } catch {}
}

/** Chime signal + O'zbekcha nutq */
export async function announceAlert(text: string, volume = 1.0): Promise<void> {
  await playChime(volume);
  await speakText(text, volume);
}

/** Sozlamalarni olish va saqlash */
export function getSavedVoiceSettings(): { enabled: boolean; role: string; volume: number } {
  try {
    const enabled = localStorage.getItem('etransport_voice_enabled') !== 'false';
    const role = localStorage.getItem('etransport_voice_role') || 'ALL';
    const volStr = localStorage.getItem('etransport_voice_volume');
    const volume = volStr ? parseFloat(volStr) : 1.0;
    return { enabled, role, volume };
  } catch {
    return { enabled: true, role: 'ALL', volume: 1.0 };
  }
}

export function saveVoiceSettings(enabled: boolean, role: string, volume: number) {
  try {
    localStorage.setItem('etransport_voice_enabled', enabled ? 'true' : 'false');
    localStorage.setItem('etransport_voice_role', role);
    localStorage.setItem('etransport_voice_volume', volume.toString());
  } catch {}
}

/** Rol mosligini tekshirish */
export function isRoleMatching(selectedRole: string, alertRole: string): boolean {
  if (!selectedRole) return true;
  const s = selectedRole.toLowerCase();
  const a = alertRole.toLowerCase();

  // Barcha xizmatlar, Admin yoki Rahbariyat barcha ogohlantirishlarni eshitadi
  if (s === 'all' || s === 'admin' || s === 'superadmin' || s === 'management' || s === 'deputydirector') {
    return true;
  }
  // Agar xabar barcha xizmatlarga mo'ljallangan bo'lsa
  if (a === 'all' || a === 'admin') {
    return true;
  }
  // Aniq rol mosligi
  if (s === a) return true;
  // ICHDX smena boshlig'i va dispetcherlik mosligi
  if ((s === 'dispatchsupervisor' || s === 'dispatching') &&
      (a === 'dispatchsupervisor' || a === 'dispatching')) {
    return true;
  }
  return false;
}


/** Ovoz eshittirilganini server audit logiga qayd etish */
export async function reportVoiceAlertDelivery(alert: WorkflowStageAlert, customRole?: string): Promise<void> {
  try {
    let username = '';
    let fullName = '';
    try {
      const stored = sessionStorage.getItem('etransport_user');
      if (stored) {
        const u = JSON.parse(stored);
        username = u?.username || '';
        fullName = u?.fullName || '';
      }
    } catch {}

    const lastRole = localStorage.getItem('etransport_last_role') || '';
    const clientRole = customRole || lastRole || 'ALL';

    await fetch('/api/public/workflow-alerts/log-delivery', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        flow: alert.flow,
        role: alert.role,
        department: alert.department,
        stageKey: alert.stageKey,
        stageTitle: alert.stageTitle,
        pendingCount: alert.pendingCount,
        voiceText: alert.voiceText,
        username: username || (lastRole ? `Navbatchi (${lastRole})` : 'Logout / Noma‘lum'),
        fullName: fullName || (lastRole ? `Navbatchi xodim (${lastRole})` : 'Anonim / Navbatchilik kompyuteri'),
        clientRole: clientRole,
        status: 'Success',
        details: `${alert.flow} jarayoni bo‘yicha ovozli ogohlantirish eshittirildi: ${alert.department} (${alert.stageTitle}, ${alert.pendingCount} ta). Matn: "${alert.voiceText}"`,
      }),
    });
  } catch {}
}

/** Serverdan navbatlarni tekshirib, ovoz chiqarish */
export async function checkAndAnnouncePendingAlerts(customRole?: string): Promise<WorkflowStageAlert[]> {
  const settings = getSavedVoiceSettings();
  if (!settings.enabled) return [];

  const targetRole = customRole || settings.role;

  try {
    const res = await fetch('/api/public/workflow-alerts');
    if (!res.ok) return [];
    const json = await res.json();
    if (!json.success || !Array.isArray(json.data)) return [];

    const alerts: WorkflowStageAlert[] = json.data;
    const matchingAlerts = alerts.filter(a => isRoleMatching(targetRole, a.role));

    const now = Date.now();
    for (const alert of matchingAlerts) {
      const alertKey = `${alert.flow}:${alert.stageKey}:${alert.role}`;
      const lastTime = lastAnnouncedTimes[alertKey] || 0;

      // Test xabari bo'lsa har safar darhol aytadi, normal bosqichlar esa har 3 daqiqada takrorlanadi
      const isTest = alert.stageKey.includes('test');
      if (isTest || now - lastTime > ANNOUNCE_COOLDOWN_MS) {
        lastAnnouncedTimes[alertKey] = now;
        await announceAlert(alert.voiceText, settings.volume);
        void reportVoiceAlertDelivery(alert, targetRole);
        break; // Bir vaqtda xabarlar aralashib ketmasligi uchun bittadan aytadi
      }
    }

    return matchingAlerts;
  } catch {
    return [];
  }
}

/** Sinov ovozini chiqarish */
export async function testVoiceForRole(roleKey: string): Promise<void> {
  const roleObj = ALERT_ROLES.find(r => r.key === roleKey) || ALERT_ROLES[0];
  const deptName = roleKey === 'ALL' ? 'Barcha mas’ul xizmatlar' : roleObj.label;
  const testText = `Diqqat! Kirish va chiqish jarayoni: ${deptName}, siz E-Transport tizimiga kirib o‘z bosqichingizni tugating!`;
  const settings = getSavedVoiceSettings();
  await announceAlert(testText, settings.volume);
  void reportVoiceAlertDelivery({
    flow: 'Sinov',
    role: roleKey,
    department: deptName,
    stageKey: 'test-voice',
    stageTitle: 'Ovoz sinovi',
    pendingCount: 1,
    voiceText: testText,
  }, roleKey);
}
